from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}  # id -> dict
        self._next_id = 1

    def _overlaps(self, a_start, a_end, b_start, b_end):
        return a_start < b_end and b_start < a_end

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start >= end:
            raise ValueError("start must be before end")
        if start <= now:
            raise ValueError("cannot book an appointment in the past")

        # At most one upcoming appointment per patient.
        for appt in self._appointments.values():
            if appt["patient"] == patient and not appt["cancelled"]:
                if appt["end"] > now:
                    raise ValueError(
                        "patient already has an upcoming appointment"
                    )

        # Check doctor availability (including cancelled-but-blocked slots).
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if appt["blocked"]:
                if self._overlaps(start, end, appt["start"], appt["end"]):
                    raise ValueError(
                        "appointment overlaps with an existing one"
                    )

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "id": appt_id,
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
            "blocked": True,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise ValueError("unknown appointment id")
        appt = self._appointments[appointment_id]
        if appt["cancelled"]:
            return
        appt["cancelled"] = True
        # If cancelled less than 24h before start, slot stays blocked.
        if now >= appt["start"] - timedelta(hours=24):
            appt["blocked"] = True
        else:
            appt["blocked"] = False

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        if start >= end:
            return False
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if not appt["blocked"]:
                continue
            if self._overlaps(start, end, appt["start"], appt["end"]):
                return False
        return True
